const THRESHOLD = 50;   // cm

// Current distances
let d1 = context.get("d1") || 100;
let d2 = context.get("d2") || 100;

// Current count
let count = context.get("count") || 0;

// Current state
let state = context.get("state") || "IDLE";

// Identify which sensor updated
if (msg.topic === "Samsungmdc/sensor/distance") {
    d1 = Number(msg.payload);
    context.set("d1", d1);
}

if (msg.topic === "Samsungmdc/sensor/distance2") {
    d2 = Number(msg.payload);
    context.set("d2", d2);
}

// --------------------
// State Machine
// --------------------

switch(state){

    case "IDLE":

        if(d1 < THRESHOLD){
            state = "S1_FIRST";
        }

        else if(d2 < THRESHOLD){
            state = "S2_FIRST";
        }

        break;

    case "S1_FIRST":

        if(d2 < THRESHOLD){
            count++;
            state = "WAIT_CLEAR";
        }

        break;

    case "S2_FIRST":

        if(d1 < THRESHOLD){
            count--;

            if(count < 0)
                count = 0;

            state = "WAIT_CLEAR";
        }

        break;

    case "WAIT_CLEAR":

        if(d1 > THRESHOLD && d2 > THRESHOLD){
            state = "IDLE";
        }

        break;
}

context.set("state", state);
context.set("count", count);

flow.set("visitorCount", count);

msg.payload = count;

return msg;

